SELECT l.id, l.data_type, l.biz_id, l.operation_type, l.data_snapshot, l.create_by, l.create_time, l.update_by, l.update_time FROM tab_app_data_change_log l INNER JOIN ( SELECT biz_id, MAX(id) AS max_id FROM tab_app_data_change_log WHERE data_type = #{dataType} AND biz_id IN
#{bizId}
GROUP BY biz_id ) latest ON latest.biz_id = l.biz_id AND latest.max_id = l.id ORDER BY l.biz_id ASC

SELECT id, data_type, biz_id, operation_type, data_snapshot, create_by, create_time, update_by, update_time
FROM tab_app_data_change_log
WHERE id > #{fromSequence}
AND data_type IN

    #{dataType}

ORDER BY id ASC
LIMIT #{limit}
